cpp.setup:
auto* control = new fluent::layout::Accordion(%PARENT%);
auto makeSection = [](const QString& title, const QString& detail) {
    auto* item = new fluent::layout::Expander;
    item->setHeaderText(title);
    auto* body = new QWidget(item);
    auto* bodyLayout = new QVBoxLayout(body);
    bodyLayout->setContentsMargins(16, 12, 16, 14);
    bodyLayout->setSpacing(4);
    auto* label = new fluent::textfields::Label(detail, body);
    label->setWordWrap(true);
    bodyLayout->addWidget(label);
    item->setContentWidget(body, fluent::WidgetOwnership::Owned);
    return item;
};
auto* general = makeSection(QStringLiteral("Account"), QStringLiteral("Profile, sign-in, and recovery options."));
general->setExpandedAnimated(true, false);
control->addItem(general, fluent::WidgetOwnership::Owned);
control->addItem(makeSection(QStringLiteral("Privacy"), QStringLiteral("Diagnostics and telemetry permissions.")), fluent::WidgetOwnership::Owned);
